for i in range(16):
    o = observe()
    if o['status'] in ('FINISHED', 'TIME_UP', 'DNF'):
        break
    bearing = o.get('route', {}).get('bearing_deg', 0)
    steer = max(-25, min(25, 2.0 * o['hitch_deg'] - 1.2 * bearing))
    remaining = o['progress']['remaining']
    step = min(1.8, max(0.35, remaining - 0.2))
    try:
        drive(steer, -step, 2.0)
    except LegOver:
        break
print(report())

try:
    for i in range(12):
        o = observe()
        if o['status'] in ('FINISHED', 'TIME_UP', 'DNF'):
            break
        h = o['hitch_deg']
        b = o.get('route', {}).get('bearing_deg', 0)
        steer = max(-35, min(35, 2.2*h - 0.7*b))
        r = drive(steer, -0.4, 0.8)
        print(i, r['obs']['hitch_deg'], r['obs']['progress'])
except LegOver:
    pass
print(report())

